function main() {
    const s = fs.readFileSync('/dev/stdin', 'utf8').trim();
    let solve = "";
    const N = s.length;

    for (let I = 0; I < N; ++I) {
        if (I + 3 <= N && s.substring(I, I + 3) === "dot") {
            solve += ".";
            I += 2;
        } else if (I + 2 <= N && s.substring(I, I + 2) === "at") {
            solve += "@";
            I += 1;
        } else {
            solve += s[I];
        }
    }

    function check() {
        if (solve.length > 0) {
            if (solve[0] === '.') {
                solve = solve.slice(1);
                solve = "dot" + solve;
            } else if (solve[0] === '@') {
                solve = solve.slice(1);
                solve = "at" + solve;
            }
        }

        const len = solve.length;
        if (len > 0) {
            if (solve[len - 1] === '.') {
                solve = solve.slice(0, len - 1) + "dot";
            } else if (solve[len - 1] === '@') {
                solve = solve.slice(0, len - 1) + "at";
            }
        }
    }

    check();

    let cont = 0;
    for (let I = 0; I < solve.length; ++I) {
        if (solve[I] === '@') ++cont;
    }

    let output = "";
    if (cont === 1) {
        output = solve;
    } else {
        let ok = true;
        for (let I = 0; I < solve.length; ++I) {
            if (solve[I] === '@') {
                if (ok) {
                    output += '@';
                    ok = false;
                } else {
                    output += "at";
                }
            } else {
                output += solve[I];
            }
        }
    }

    console.log(output);
}

main();

